-- 게임 버전별 업데이트 노트.
--
-- 전 게임 공통 패널이라 게임마다 표를 따로 두지 않는다. 정렬은 released_at 역순이고,
-- 같은 날 여러 판이 나가면 version 이 가른다.
--
-- 본문은 한 줄 요약이 아니라 문단이다 — 「무엇이 바뀌었나」를 읽으러 온 자리라
-- 짧게 자르면 바꾼 이유가 사라진다. 한글은 hex 로 넣는다(리터럴은 조용히 이중 인코딩).
CREATE TABLE game_release_note (
    id          BIGINT       NOT NULL AUTO_INCREMENT,
    game_id     BIGINT       NOT NULL,
    version     VARCHAR(32)  NOT NULL,
    released_at DATE         NOT NULL,
    body        TEXT         NOT NULL,
    body_en     TEXT         NULL,
    PRIMARY KEY (id),
    UNIQUE KEY uk_game_release_note (game_id, version),
    KEY idx_game_release_note_game (game_id, released_at)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4;

-- 궁수 키우기 — 베타 딱지를 뗀다. 상태가 정식 축이고 `beta` 태그는 쓰지 않는다.
UPDATE game SET status = 'PUBLISHED' WHERE slug = 'archer-outbreak';

-- **INSERT 를 하나로 묶어 UNION 하지 않는다.** 파생 테이블에서 0x 리터럴을 UNION 하면
-- 결과 열의 폭이 분기들에 따라 정해지는데, 그 규칙에 기대면 긴 본문이 조용히 잘릴 수 있다.
INSERT INTO game_release_note (game_id, version, released_at, body)
SELECT g.id, '1.0', '2026-08-30', CONVERT( USING utf8mb4)
FROM game g WHERE g.slug = 'archer-outbreak';

INSERT INTO game_release_note (game_id, version, released_at, body)
SELECT g.id, '0.9', '2026-08-29', CONVERT( USING utf8mb4)
FROM game g WHERE g.slug = 'archer-outbreak';

